"""Generate the Study III-D registered-design and simulation report."""
from pathlib import Path
from xml.sax.saxutils import escape
import json
import numpy as np
import pandas as pd
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from reportlab.lib import colors
from reportlab.lib.styles import getSampleStyleSheet,ParagraphStyle
from reportlab.lib.pagesizes import A4
from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,Table,TableStyle,Image,PageBreak
from design import ROOT,RESULTS,write,verify_predecessors

OUT=ROOT/'output/pdf'
FIG=RESULTS/'figures'
NAVY=colors.HexColor('#132D46');TEAL=colors.HexColor('#087E8B');GREY=colors.HexColor('#526579')
styles=getSampleStyleSheet()
for name,size,lead,bold,color in [('TitleX',27,32,True,NAVY),('H1X',18,23,True,NAVY),('H2X',11.5,16,True,TEAL),('BodyX',10,14.5,False,NAVY),('SmallX',8.2,11.4,False,GREY),('CellX',8.4,11.2,False,NAVY),('HeadX',8.4,11.2,True,colors.white)]:
    styles.add(ParagraphStyle(name=name,fontName='Helvetica-Bold' if bold else 'Helvetica',fontSize=size,leading=lead,textColor=color,spaceAfter=9 if name!='CellX' else 0))

def p(text,style='BodyX'):return Paragraph(text,styles[style])
def h(text):return p(text,'H1X')
def sub(text):return p(text,'H2X')
def table(rows,widths):
    t=Table([[p(escape(str(c)),'HeadX' if i==0 else 'CellX') for c in row] for i,row in enumerate(rows)],colWidths=widths,repeatRows=1,hAlign='LEFT')
    t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),NAVY),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.HexColor('#F0F5F8'),colors.white]),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),7),('RIGHTPADDING',(0,0),(-1,-1),7),('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),6)]))
    t.spaceAfter=9;return t
def img(name,width=491):
    im=Image(str(FIG/name));im.drawHeight=width*im.imageHeight/im.imageWidth;im.drawWidth=width;return im
def pct(x):return f'{100*x:.1f}%'
def yes(x):return 'Pass' if x else 'Fail'
def short(s):return {'block5':'Block 5','block10':'Block 10','block20':'Block 20','block40_stress':'Block 40 stress','block20_scale125_stress':'Block 20, scale 1.25'}[s]

def main():
    OUT.mkdir(parents=True,exist_ok=True);FIG.mkdir(parents=True,exist_ok=True)
    summary=pd.read_csv(RESULTS/'VALIDATION_SUMMARY.csv');gates=pd.read_csv(RESULTS/'SAMPLE_SIZE_GATES.csv')
    decision=json.loads((RESULTS/'DESIGN_DECISION.json').read_text());scale=json.loads((RESULTS/'PILOT_SCALE.json').read_text())
    critical=json.loads((RESULTS/'FROZEN_CRITICAL_VALUE.json').read_text());run=json.loads((RESULTS/'RUN_SCOPE.json').read_text())
    registry=json.loads((ROOT/'protocol/REGISTRATION.json').read_text()) if (ROOT/'protocol/REGISTRATION.json').exists() else {}
    s0=scale['S0'];c=critical['critical_value'];atcap=summary[summary.n==1975]
    feasible=decision['capacity_sufficient'];minimum=decision['minimum_scored_n']
    selected=f'{minimum:,}' if minimum is not None else 'None within the frozen grid'
    prior=verify_predecessors()
    fig,ax=plt.subplots(figsize=(8.8,3.6))
    for scenario,g in summary.groupby('scenario'):
        a=g.groupby('n').precision_lower95.min();ax.plot(a.index,a.values*100,marker='o',ms=3,label=short(scenario))
    ax.axhline(80,color='#132D46',ls='--',label='Required lower bound: 80%')
    ax.axvline(1975,color='#526579',ls=':',label='OANDA capacity upper bound: 1,975')
    ax.set_xlabel('Scored synthetic forecasts (400 training observations separate)');ax.set_ylabel('Worst precision-success 95% MC lower bound (%)')
    ax.set_ylim(-2,102);ax.set_title('Probability of meeting the frozen interval-width target',loc='left',fontsize=11)
    ax.legend(frameon=False,fontsize=7,ncol=2);ax.spines[['top','right']].set_visible(False);fig.tight_layout();fig.savefig(FIG/'precision_probability.png',dpi=180);plt.close(fig)
    fig,ax=plt.subplots(figsize=(8.8,3.6))
    for scenario,g in summary.groupby('scenario'):
        a=g.groupby('n').width_p80.max()*100;ax.plot(a.index,a.values,marker='o',ms=3,label=short(scenario))
    ax.axhline(10,color='#132D46',ls='--',label='Frozen full width: 10% of pilot loss')
    ax.axvline(1975,color='#526579',ls=':');ax.set_xlabel('Scored synthetic forecasts (400 training separate)');ax.set_ylabel('Worst 80th-percentile full width (% of fixed pilot loss)')
    ax.set_title('Dependence and volatility determine achievable precision',loc='left',fontsize=11)
    ax.legend(frameon=False,fontsize=7,ncol=2);ax.spines[['top','right']].set_visible(False);fig.tight_layout();fig.savefig(FIG/'interval_width.png',dpi=180);plt.close(fig)
    fig,ax=plt.subplots(figsize=(8.8,3.3))
    for scenario,g in summary[summary.target_effect==.05].groupby('scenario'):
        ax.plot(g.n,g.positive_lower_rate*100,marker='o',ms=3,label=short(scenario))
    ax.set_xlabel('Scored synthetic forecasts');ax.set_ylabel('Positive lower-bound probability (%)')
    ax.set_ylim(-2,102);ax.set_title('Descriptive rejection probability at the 5% calibration target',loc='left',fontsize=11)
    ax.legend(frameon=False,fontsize=7,ncol=2);ax.spines[['top','right']].set_visible(False);fig.tight_layout();fig.savefig(FIG/'descriptive_power.png',dpi=180);plt.close(fig)

    story=[Spacer(1,14),p('Study III-D<br/>Precision-based confirmation<br/>of cross-session information','TitleX'),p('Registered design development and independent simulation audit','H2X'),p('XAU/USD | Asian realised variance -> subsequent London realised variance | 11 October 2026'),Spacer(1,10),sub('Decision')]
    story += [p('<b>'+('The precision design is capacity-eligible, subject to a separate public empirical freeze.' if feasible else 'The frozen precision/validation/capacity gates do not authorise fresh confirmation.')+'</b>'),p(f'The prespecified minimum-score selection returns <b>{escape(selected)}</b>. Existing OANDA timestamp coverage permits at most <b>1,975</b> fresh scored dates after reserving 400 training dates. This is an optimistic ceiling, not a quality-audited empirical sample.'),p('No pre-2016 numerical prices were opened, no fresh forecast outcomes were evaluated, no strategy was run, and the final 2024+ holdout remains closed. Study III-D is a new design and does not amend III-C.'),sub('What changed'),p('The scientific question is unchanged. The decision framework now requires a positive dependence-robust interval and a predefined maximum uncertainty, rather than a 90%-power requirement against a 5% effect. Changing the framework does not by itself create more precise evidence.'),p('All results below are synthetic planning evidence using only already-viewed 2016-2023 calibration. Synthetic observations and 252-step subperiods are never presented as historical market dates.','SmallX'),PageBreak()]

    story += [h('1. Question, estimand and precision'),p('Does the Asian state contain reproducible incremental information for London RV beyond HAR? Define Delta as HAR QLIKE loss minus HAR+Asia QLIKE loss. A positive mean favours HAR+Asia.'),p('The operational estimand is the long-run expected loss advantage of the particular frozen pair fitted to the first 400 eligible fresh labels, conditional on that fitted pair and a sufficiently stable confirmation-period distribution. It is not an unconditional retraining effect or a causal intervention in the gold market.'),sub('A fixed scale prevents denominator ambiguity'),p(f'The already-viewed pilot fixes <b>S0={s0:.9f}</b>, the mean HAR QLIKE after training on {scale["first_training"]} to {scale["last_training"]} ({scale["training_rows"]} eligible rows) and forecasting {scale["first_scored"]} to {scale["last_scored"]} ({scale["scored_rows"]:,} rows). This is nuisance calibration, not fresh confirmation.'),p(f'The maximum two-sided full interval width is <b>0.10 x S0 = {s0*.10:.9f}</b> raw QLIKE units. Thus the half-width resolution is about +/-5% of the fixed pilot baseline loss. It is not a 10-percentage-point CI for fresh relative improvement; the fresh denominator would be different and random.'),p('The realised fresh relative gain, mean Delta / mean fresh HAR loss, is a secondary descriptive statistic. It does not replace the frozen precision denominator.'),table([['Prospective choice','Frozen rule'],['Minimum considered scores','1,000; at least four populated annual subperiods'],['Planning grid','1,000 / 1,250 / 1,500 / 1,750 / 1,975 / 2,500 / 3,000 / 4,000'],['Precision assurance','95% MC lower bound >=80% for meeting width in every scenario/signal cell'],['Evaluation schedule','All eligible fresh data to 2015-12-31; one evaluation; no favourable stopping']],[150,341]),PageBreak()]

    story += [h('2. Measurement and causal forecasting'),table([['Window','Clock and role'],['Asia','09:00-15:00 Asia/Tokyo = 00:00-06:00 UTC; current feature'],['London','08:00-12:00 Europe/London; DST via named timezone; subsequent target'],['Daily','UTC00:00-24:00; only completed prior daily RV is a predictor']],[104,387]),p('Use native unsmoothed M5 midpoint candles. One common set of squared-return edges is partitioned into A, L and remainder R; D=A+L+R. Consecutive received closes must be five minutes apart within a UTC day. The first daily bar uses open-to-close. Gaps are never bridged or filled.'),p('HAR uses previous valid log L, previous valid log D, and log prior 5/20-valid-L means. HAR+Asia adds current log A. Previous single-session/daily values must be no older than four calendar days. All rolling windows exclude the current London target.'),p('Both log-RV models fit intercept and unpenalised OLS on exactly 400 initial eligible labels. Back-transform using the training-only mean exp(residual), then freeze coefficients and smearing. Subsequent available history updates predictors only. Variance predictions have a 1e-12 floor; nonfinite values stop the procedure.'),sub('Quality and issuance'),p('Retain III-B quality criteria: sessions >=95% of expected M5 bars, both boundaries, max received gap10min; daily >=85%, max gap90min. Flag unordered/nonfinite OHLC, nonpositive open/close bid-ask spreads, spreads above USD5, and adjacent-bar opening jumps above2%. No flagged session is rescued by deleting individual bars.'),p('At06:00UTC only completed Asian and prior-window quality can determine issuance. Current London or later-day quality cannot cancel an already issued forecast. A dedicated timing test checks this; another compares the entire reconstructed 2016-2023 feature ledger with the frozen III-C pilot.'),p('Source-specific confirmation remains OANDA-only. A new period on the same provider is fresh chronology, not independent-feed replication.','SmallX'),PageBreak()]

    story += [h('3. Full-procedure simulation and risk reference'),p('The III-C generator is reused without rewriting its frozen files. It generates positive Asia, London and remainder RV recursively and constructs daily RV exactly as their sum. Every future HAR input comes from generated history. Forecast fits remain ordinary OLS even though the nuisance generator has its documented stability constraints.'),table([['Scenario family','Innovation resampling'],['Core dependence','Circular residual blocks5,10,20'],['Persistence stress','Blocks40'],['Volatility stress','Blocks20; all log-innovation residuals multiplied by1.25'],['Signals','Zero channel; existing 1%,5%,10% long-training calibration targets']],[150,341]),p('Asia innovations are resampled independently of joint London/remainder innovations. Within-stream dependence and London/remainder joint dependence survive; the full original joint distribution does not. The intervention controls the Asia channel rather than shifting forecast losses.'),p('Each independent synthetic path uses 500 burn-in steps, 400 training observations, and up to4,000 scored observations. Every fitted pair has an independently integrated stationary risk reference: 64 paths x8,192 scored steps, with separate seeds and burn-in. The reference uses the same prediction floor, fitted coefficients and training-only smearing.'),p('Reference uncertainty is measured across independent paths. Calibration and coverage use a +/-2.58 integration-SE bracket; independent half-reference coverage and oracle-SE/evaluation-SE are also reported. This is approximate integration of a stationary risk, not an exact finite-horizon conditional expectation.'),p(f'Completed: {run["calibration_paths"]:,} calibration fits, {run["independent_validation_paths"]:,} independent validation fits and {run["independent_reference_paths"]:,} reference trajectories. The generator stopped on any containment/nonfinite failure; recorded component violations: {run["component_containment_violations"]}.','SmallX'),PageBreak()]

    story += [h('4. Interval construction and error calibration'),p('For each loss path, compute the exact conditional circular-bootstrap variance of its mean at blocks5,10,20, including the short final block. Take the largest SE. No inner-bootstrap Monte Carlo noise enters this SE.'),p(f'The primary interval is <b>mean Delta +/- {c:.6f} x maxSE</b>. The common critical value is calibrated from the highest 97.5th percentile of absolute studentised reference error plus integration uncertainty, over all planning N/scenario/signal cells, with a minimum1.959964. It was saved before independent validation.'),p('This deliberately conservative, simulation-calibrated interval has a block-bootstrap SE; it is not a percentile bootstrap interval and does not have a distribution-free95% guarantee. Calibration across the finite planning grid helps protect prospective N selection within the stated scenarios.'),sub('Independent validation at the known OANDA ceiling'),table([['Scenario','Coverage lower*','Boundary upper*','Null upper*'],*[[short(s),pct(g.bracket_coverage_lower95.min()),pct(g.boundary_upper_one_sided95.max()),pct(g[g.target_effect==0].positive_lower_upper_one_sided95.iloc[0])] for s,g in atcap.groupby('scenario')]],[167,108,108,108]),p('* Monte Carlo bounds: two-sided95% Wilson lower for full reference-bracket coverage; one-sided95% Wilson upper for upper-tail noncoverage and zero-channel false positive lower-bound decisions. Worst signal is shown except the zero-channel column. Gates: coverage lower>=93%; boundary/null upper<=6%.','SmallX'),p('A zero-direct-Asia-channel model is not an exact equal-forecast-risk null after finite estimation. Consequently its rejection rate is an operational false-confirmation diagnostic. Boundary noncoverage and full reference-risk coverage assess interval error separately; neither is a universal size theorem.'),p(f'The worst oracle-SE/evaluation-SE 95th percentile at N4,000 is {summary[summary.n==4000].oracle_se_ratio_p95.max():.3f}; frozen limit0.20. Maximum difference between the two half-reference coverage estimates: {pct(summary.coverage_half_reference_difference.max())}.','SmallX'),PageBreak()]

    story += [h('5. Precision sufficiency'),img('precision_probability.png'),p('Each curve takes the worst signal at that scenario/N. The plotted quantity is the two-sided95% Wilson lower bound for the proportion of independent paths whose full interval width is <=10% of fixed pilot loss. All curves must clear80%; significance probability is not the selection criterion.','SmallX'),img('interval_width.png'),p('The second chart shows the worst 80th-percentile width across signals. Its10% line is the unchanged precision target. The vertical line is the1,975-score coverage ceiling, before price-quality exclusions. The cells are synthetic and do not estimate an observed pre-2016 effect.','SmallX'),PageBreak()]

    story += [h('6. Frozen sample selection and descriptive power'),table([['N','Coverage','Boundary','Precision','All gates'],*[[f'{int(g.n):,}',yes(g.coverage_pass),yes(g.boundary_pass),yes(g.precision_pass),yes(g.all_pass)] for _,g in gates.iterrows()]],[70,105,105,105,106]),p('Null and oracle gates are included in "All gates"; full values are in SAMPLE_SIZE_GATES.csv. Select the smallest N whose gates pass at that N and every larger listed N. No alternate threshold or narrower scenario set is selected after validation.'),p(f'<b>Selected minimum: {escape(selected)}.</b> This rule uses prospective simulations only. If no N passes the finite grid, it does not imply that no larger design could ever pass; it does stop this frozen candidate.'),img('descriptive_power.png'),p('These curves show only the probability of a positive lower bound at the5% long-training calibration target. Achieved finite-400-training gains and the stricter joint acceptance rates are recorded separately. They are not power guarantees or empirical confirmations.','SmallX'),PageBreak()]

    story += [h('7. Source capacity and empirical decision'),table([['Requirement/evidence','Status'],['III-C required scored dates','4,000; unchanged'],['Existing OANDA ceiling','1,975, after400 initial training labels; coverage-only'],['III-D selected minimum',selected],['III-D capacity eligibility',yes(feasible)],['Fresh numerical prices opened in III-D','No'],['Fresh forecast confirmation run','No'],['2024+ final holdout','Unopened'],['Trading translation or execution','Not run'],['Route A','Administratively open for provider evidence']],[228,263]),p('The existing audit found complete native-M5 candles beginning19March2006 and ending31December2015. A1999 search bound is not a claim of1999 history. Coverage, positive-RV and quote-quality exclusions can reduce the1,975 upper bound; nothing in III-D manufactures extra dates.'),p('The III-C power/capacity failure remains unchanged. III-D changes the prospective objective and uncertainty requirement, not the underlying unique-date count, and not the substantive forecasting question.'),sub('Current action'),p(escape(decision['next_action'])+'.'),p('Provider answers may still establish a qualifying historical source. They require instrument-specific timestamp evidence, original two-sided quote provenance, historical clocks, source-change documentation and suitable licence rights. A different source does not automatically inherit OANDA measurement equivalence or these simulation results.'),p('Olsen and Tickdatamarket enquiries were sent6October2026. LSEG acknowledged a sales contact request; its form accepted an abbreviated topic and needs the full checklist on follow-up. No provider suitability finding is inferred from sending an enquiry. No additional outreach is made in this phase.','SmallX'),PageBreak()]

    story += [h('8. Prospective confirmation specification'),p('This specification is inert unless design validation and capacity pass and a public source-specific freeze authorises opening quarantine. The cached-only runner has no candle-API acquisition code and checks design, registry, code hashes and predecessor preservation before accessing numerical fresh inputs.'),table([['Gate','Predefined rule'],['Sample and evaluation','All eligible issued/scorable dates after the first400 labels through2015-12-31; N>=registered minimum; >=95% issued-label coverage'],['Incremental QLIKE','Calibrated primary lower bound>0'],['Precision','Full interval width<=0.10 x frozen pilot HAR loss'],['Asia slope','Frozen fitted coefficient>0'],['MSE/MAE','Each enhanced/baseline ratio<=1.05'],['Calendar consistency','>=4 years with>=100 scores; positive yearly paired mean in>=ceil(2/3) of those years'],['Sensitivity','Report all years; calendar-position paired percentile bootstrap9,999 draws at blocks5/10/20'],['Further holdout','Separate final protocol;2024+ stays closed here']],[132,359]),p('Primary blocks count consecutive scorable forecasts, not elapsed calendar days. The secondary percentile procedure retains missing/unissued business-day positions. Simulations model complete eligible-step sequences; arbitrary calendar missingness and outcome-dependent quality exclusions are not calibrated generator features.'),p('If source quality reduces eligible N below the minimum, stop before model fitting/loss evaluation. A sample or precision failure is reported honestly; no threshold relaxation, selective year omission, model refitting or repeated confidence-interval checking is allowed.'),p('Public GitHub versioning provides a prospective, reviewable record before numerical fresh access. It is not an OSF registration, institutional endorsement or an independently certified timestamp. This development report does not claim a passed empirical test.','SmallX'),PageBreak()]

    story += [h('9. Evidence limits, references and preservation'),sub('Interpretation limits'),p('The coherent generator is conditional on the viewed pilot law, stability constraints and intervention in residual dependence. Block40 and1.25-scale scenarios stress two dimensions; they do not cover arbitrary structural breaks, biased RV, old-provider microstructure, all missingness mechanisms or every heavy-tailed law. Reference integration is approximate and targets stationary conditional risk.'),p('M5 equivalence within OANDA establishes agreement with the stated measurement construction, not that measured RV is an unbiased latent-variance proxy. QLIKE robustness results require assumptions; MAE remains only a secondary practical guardrail. HAR is adapted across sessions, not an exact replication of the original daily HAR-RV model.'),sub('Primary references')]
    for ref in json.loads((ROOT/'protocol/REFERENCES.json').read_text()):
        story.append(p(f'<b>{escape(ref["authors"])} ({ref["year"]}).</b> <link href="{escape(ref["url"])}" color="#087E8B">{escape(ref["title"])}</link>. {escape(ref["use"])}','SmallX'))
    story += [sub('Audit trail and immutable predecessors'),p(f'Verified {prior} tracked predecessor files unchanged. Source-lock hashes cover the reused III-C routines and pilot derivatives; per-path calibration/validation statistics and all160 validation cells accompany this report. Original Studies I/II, Study III Design Pack, III-B, III-C and Route A remain intact.'),p('Development scope and implementation were committed before new simulations. Calibration critical values were committed before independent validation. Final registration records which gates passed or failed, code/protocol hashes and continued outcome closure. Protocol choices and unsuccessful design outcomes are retained rather than overwritten.','SmallX'),p('No completion percentage or profitable-strategy claim is made. The report is a prospective methodology result, not an investment recommendation.','SmallX')]

    def page(canvas,doc):
        canvas.setStrokeColor(TEAL);canvas.line(52,805,543,805);canvas.setFillColor(GREY);canvas.setFont('Helvetica',8)
        canvas.drawString(52,817,'XAUUSD RESEARCH / STUDY III-D')
        canvas.drawString(52,29,'Precision-based confirmation design | 11 October 2026')
        canvas.drawRightString(543,29,str(doc.page))
    pdf=OUT/'Study_III_D_Precision_Design_and_Validation_Report.pdf'
    SimpleDocTemplate(str(pdf),pagesize=A4,leftMargin=52,rightMargin=52,topMargin=54,bottomMargin=48,title='Study III-D: Precision Design and Validation',author='XAUUSD Research').build(story,onFirstPage=page,onLaterPages=page)
    print('Report generated:',pdf,flush=True)

if __name__=='__main__':main()
